typedef int int32;
class PhysicsObjectClass;
typedef void (*OdeDerivFunc)(PhysicsObjectClass* phyobj, float rTime,
   float* rInStateArray, float* rOutStateArray);
extern void *arch_malloc(unsigned int size, const char *desc, int line);
extern const char ode_init_description[];
__asm__(".equ arch_malloc__FUiPCci, 0x002AC6F0");
__asm__(".equ ode_init_description, 0x004D2CF0");
#define malloc(size) arch_malloc(size, ode_init_description, 0)

class RungeKuttaClass
{
public:
	int32 Init(int d, float step, OdeDerivFunc dfn);
private:
	int32 dim;
	float stepSize;
	OdeDerivFunc fnDerivFunc;
	char vtable[4];
	float step2, step6;
	float* temp1;
	float* temp2;
	float* temp3;
	float* temp4;
	float* xtemp;
};

int32 RungeKuttaClass::Init(int d, float step, OdeDerivFunc dfn)
{
	this->dim = d;
	this->stepSize = step;
	this->fnDerivFunc = dfn;


	this->step2 = step/2.0f;
	this->step6 = step/6.0f;

	this->temp1 = (float*)malloc(sizeof(float) * d);
	this->temp2 = (float*)malloc(sizeof(float) * d);
	this->temp3 = (float*)malloc(sizeof(float) * d);
	this->temp4 = (float*)malloc(sizeof(float) * d);
	this->xtemp = (float*)malloc(sizeof(float) * d);

	if(!this->temp1 || !this->temp2 || !this->temp3 || !this->temp4 || !this->xtemp)
		return -1;

	return 1;

}
